 private val app=application as WorkbenchApplication;private val repository=app.repository;private val store=AiProviderCatalogStore(application);private val _catalog=MutableStateFlow(store.load());val catalog:StateFlow<AiProviderCatalog> =_catalog;private val _conversationId=MutableStateFlow<String?>(null);val conversationId:StateFlow<String?> =_conversationId;val activeDocument=ActiveWorkspaceDocumentBridge.document
 val conversations=activeDocument.flatMapLatest{d->if(d==null)flowOf(emptyList())else repository.conversations(d.workspaceId)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5_000),emptyList());val messages=_conversationId.flatMapLatest{if(it==null)flowOf(emptyList())else repository.messages(it)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5_000),emptyList())
 private val _attachments=MutableStateFlow<List<WorkspaceContextAttachment>>(emptyList());val attachments=_attachments.asStateFlow();private val _attachmentMessage=MutableStateFlow("");val attachmentMessage=_attachmentMessage.asStateFlow();private val _loadingAttachment=MutableStateFlow(false);val loadingAttachment=_loadingAttachment.asStateFlow();private val _searchPage=MutableStateFlow<WorkspaceSearchPage?>(null);val searchPage=_searchPage.asStateFlow();private val _searching=MutableStateFlow(false);val searching=_searching.asStateFlow();private val _generation=MutableStateFlow(AiGenerationState());val generation=_generation.asStateFlow();private val _agentRounds=MutableStateFlow<List<ReadonlyAgentRound>>(emptyList());val agentRounds=_agentRounds.asStateFlow();val persistedSubAgentRuns=messages.map{list->list.flatMap{m->AgentRunMetadata.subAgentReportRefs(m.toolCallsJson).map{PersistedSubAgentRun(m.id,it)}}}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5_000),emptyList())
 private var job:Job?=null;private val search=WorkspaceReadonlySearch(WorkspaceDocumentTextReader{readText(it.uri)})
