 private fun profile():AiProviderProfile?{_catalog.value=store.load();val s=_catalog.value.defaultModel?:return null;return _catalog.value.providers.firstOrNull{it.id==s.providerId}}
 fun refreshConfiguration(){_catalog.value=store.load()};fun newConversation(){if(job?.isActive==true)return;_conversationId.value=null;_attachments.value=emptyList();_agentRounds.value=emptyList();_generation.value=AiGenerationState();_checkpoints.value=emptyList()};fun openConversation(id:String){if(job?.isActive==true)return;viewModelScope.launch{val d=activeDocument.value?:return@launch;val c=repository.conversation(id)?:return@launch;if(c.workspaceId!=d.workspaceId){_attachmentMessage.value="拒绝打开其他工作区的对话";return@launch};_conversationId.value=id;_attachments.value=emptyList();_agentRounds.value=emptyList();_generation.value=AiGenerationState();loadCheckpoints()}}
 fun readPersistedToolResult(resultId:String,offset:Int=0,limit:Int=32_768):AgentToolResultPage{val d=activeDocument.value?:error("当前没有工作区");val c=_conversationId.value?:error("当前没有对话");return FileAgentToolResultStore(File(app.filesDir,"agent-tool-results/${d.workspaceId}/$c"),d.workspaceId,c).read(resultId,offset,limit.coerceIn(1,1_000_000))}
 fun searchWorkspace(q:String,caseSensitive:Boolean=false,offset:Int=0){val d=activeDocument.value?:return;if(q.isBlank())return;viewModelScope.launch{_searching.value=true;runCatching{val r=app.database.recentFiles().observe(d.workspaceId).first();val s=repository.sources().first().filter{it.workspaceId==d.workspaceId};search.search(buildList{add(WorkspaceSearchDocument(d.workspaceId,d.uri,d.title));r.forEach{add(WorkspaceSearchDocument(it.workspaceId,it.uri,it.name))};s.forEach{add(WorkspaceSearchDocument(it.workspaceId?:d.workspaceId,it.uri,it.name))}},q,0,caseSensitive)}.onSuccess{_searchPage.value=it}.onFailure{_attachmentMessage.value=WorkbenchErrorMapper.map(it,0).userFacing.displayText};_searching.value=false}}
 fun nextSearchPage(){};fun attachSearchMatch(m:WorkspaceSearchMatch){viewModelScope.launch{_loadingAttachment.value=true;runCatching{WorkspaceContextAttachmentFactory.fromCompleteText(m.workspaceId,m.uri,m.title,readText(m.uri))}.onSuccess{_attachments.value+=it}.onFailure{_attachmentMessage.value=WorkbenchErrorMapper.map(it,0).userFacing.displayText};_loadingAttachment.value=false}};fun attachCurrentFileRange(s:Int,e:Int){val d=activeDocument.value?:return;viewModelScope.launch{_loadingAttachment.value=true;runCatching{WorkspaceContextAttachmentFactory.fromCompleteText(d.workspaceId,d.uri,d.title,readText(d.uri))}.onSuccess{_attachments.value+=it}.onFailure{_attachmentMessage.value=WorkbenchErrorMapper.map(it,0).userFacing.displayText};_loadingAttachment.value=false}}
 private suspend fun readText(uri:String)=withContext(Dispatchers.IO){app.contentResolver.openInputStream(Uri.parse(uri))?.use{String(it.readBytes(),Charsets.UTF_8)}?:error("无法打开 $uri")};fun removeAttachment(id:String){_attachments.value=_attachments.value.filterNot{it.id==id}}
 private fun activeSelection():AiModelSelection?{val localActive=_localRuntime.value&&localStore.load().configured;if(localActive)return AiModelSelection(LOCAL_RUNTIME_PROVIDER_ID,localStore.load().model);val lanActive=_lanRuntime.value&&lanStore.load().configured;if(lanActive)return AiModelSelection(LAN_RUNTIME_PROVIDER_ID,lanStore.load().model);return _catalog.value.defaultModel}
 fun send(text:String){if(text.isBlank())return;refreshConfiguration();val selection=activeSelection()?:return;val d=activeDocument.value?:return;if(job?.isActive==true){viewModelScope.launch{enqueueMessage(text,d.workspaceId)};return};job=viewModelScope.launch{executeSend(text,selection,d.workspaceId)}}
 private suspend fun executeSend(text:String,selection:com.uma.workbench.agent.AiModelSelection,wsId:String){val chosen=_attachments.value.toList();val conv=ensureConversation(text);val modeContext=com.uma.workbench.agent.ActiveModeBridge.mode.value.systemPromptFragment();val history=listOf(AiPromptMessage("system",modeContext))+messages.value.map{AiPromptMessage(it.role.lowercase(),it.content)}+AiPromptMessage("user",WorkspaceContextPromptComposer.compose(text,chosen));repository.addMessage(MessageEntity(UUID.randomUUID().toString(),conv,null,null,repository.nextMessageSequence(conv),"user",text,createdAt=System.currentTimeMillis(),toolCallsJson=WorkspaceContextPromptComposer.metadataJson(chosen)));val requestId=UUID.randomUUID().toString();_attachments.value=emptyList();_agentRounds.value=emptyList();_generation.value=AiGenerationState(AiGenerationPhase.GENERATING,requestId,model=selection.modelId);val loop=AiChatRuntimeFactory.create(app,provider,wsId,conv,tier=_executionTier.value);val textBuilder=StringBuilder();var lastFlush=0L;var lastDraftSave=0L;try{val result=loop.run(AiGenerationRequest(requestId,history,selection.modelId,ReadonlyAgentToolSchemas.openAiCompatible),object:ReadonlyAgentObserver{override fun onModelEvent(round:Int,event:AiStreamEvent){if(event is AiStreamEvent.TextDelta){textBuilder.append(event.completeDelta);val now=System.currentTimeMillis();if(now-lastFlush>=80){_generation.value=_generation.value.copy(completeText=textBuilder.toString(),partialCharacterCount=textBuilder.length);lastFlush=now};if(now-lastDraftSave>=2000&&textBuilder.isNotEmpty()){lastDraftSave=now;viewModelScope.launch{saveDraftSnapshot(requestId,conv,wsId,selection.modelId,text,textBuilder.toString())}}}};override fun onRoundCompleted(round:ReadonlyAgentRound){_agentRounds.value+=round;if(round.toolCalls.isNotEmpty()){textBuilder.clear();_generation.value=_generation.value.copy(completeText="")}}});_generation.value=_generation.value.copy(phase=AiGenerationPhase.COMPLETED,completeText=result.completeAnswer,usage=result.usage,model=result.model);app.database.generationRuns().updateStatus(requestId,"COMPLETED",System.currentTimeMillis());val verification=ModelOutputVerifier.verify(result);repository.addMessage(MessageEntity(UUID.randomUUID().toString(),conv,requestId,requestId,repository.nextMessageSequence(conv),"assistant",result.completeAnswer,"COMPLETED",System.currentTimeMillis(),toolCallsJson=AgentRunMetadata.appendVerification(AgentRunMetadata.toJson(result.rounds),verification),tokenCount=result.usage.totalTokens.coerceAtMost(Int.MAX_VALUE.toLong()).toInt(),modelUsed=result.model?:selection.modelId));persistAgentRun(requestId,conv,selection.providerId,result,"COMPLETED",null)}catch(c:CancellationException){saveDraftSnapshot(requestId,conv,wsId,selection.modelId,text,textBuilder.toString());_generation.value=_generation.value.copy(phase=AiGenerationPhase.CANCELLED,completeText=textBuilder.toString());throw c}catch(e:Throwable){if(isNetworkError(e)&&textBuilder.isNotEmpty()){saveGenerationSnapshot(requestId,conv,wsId,selection.modelId,text,textBuilder.toString(),history);_generation.value=_generation.value.copy(phase=AiGenerationPhase.WAITING_FOR_NETWORK,completeText=textBuilder.toString(),partialCharacterCount=textBuilder.length)}else{_generation.value=_generation.value.copy(phase=AiGenerationPhase.FAILED,completeText=textBuilder.toString(),error=WorkbenchErrorMapper.map(e,textBuilder.length).userFacing.displayText);persistAgentRunFailed(requestId,conv,selection.providerId,selection.modelId,e)}}finally{job=null;processOutboundQueue()}}
 private suspend fun enqueueMessage(text:String,wsId:String){val convId=_conversationId.value?:ensureConversation(text);val now=System.currentTimeMillis();val nextOrder=app.database.outboundQueue().nextOrder(convId);app.database.outboundQueue().upsert(OutboundQueueEntity(id=UUID.randomUUID().toString(),conversationId=convId,workspaceId=wsId,content=text,attachmentsJson=null,queueOrder=nextOrder,status="QUEUED_AFTER_CURRENT",createdAt=now));_attachmentMessage.value="已排队，当前回复结束后自动发送"}
 private suspend fun processOutboundQueue(){val convId=_conversationId.value?:return;val pending=app.database.outboundQueue().pendingFor(convId);if(pending.isEmpty())return;val first=pending.first();app.database.outboundQueue().mark(first.id,"SENDING",null);val selection=activeSelection();if(selection==null){app.database.outboundQueue().mark(first.id,"QUEUED_AFTER_CURRENT","未选择默认模型，发送已暂停");return};executeSend(first.content,selection,first.workspaceId);if(_generation.value.phase==AiGenerationPhase.COMPLETED)app.database.outboundQueue().mark(first.id,"SENT",null)else app.database.outboundQueue().mark(first.id,"QUEUED_OFFLINE",_generation.value.error?:"生成失败，已重新排队")}
 private fun isNetworkError(e:Throwable):Boolean{val s=e.toString();return s.contains("Software caused connection abort",true)||s.contains("Connection reset",true)||e is java.net.SocketException||e is java.net.ConnectException||e is java.net.UnknownHostException||e is java.net.SocketTimeoutException||e is javax.net.ssl.SSLException}
 private suspend fun saveGenerationSnapshot(requestId:String,convId:String,wsId:String,model:String,userMessage:String,receivedText:String,history:List<AiPromptMessage>){val now=System.currentTimeMillis();val snapshot=GenerationRunEntity(requestId=requestId,conversationId=convId,workspaceId=wsId,model=model,systemPrompt=null,userMessage=userMessage,messagesSnapshot=history.joinToString("\n"){it.role+":"+it.completeContent},receivedText=receivedText,lastEventId=null,toolCallsJson=null,usageJson=null,status="WAITING_FOR_NETWORK",createdAt=now,updatedAt=now);app.database.generationRuns().upsert(snapshot)}
 private suspend fun saveDraftSnapshot(requestId:String,convId:String,wsId:String,model:String,userMessage:String,receivedText:String){val now=System.currentTimeMillis();app.database.generationRuns().upsert(GenerationRunEntity(requestId=requestId,conversationId=convId,workspaceId=wsId,model=model,systemPrompt=null,userMessage=userMessage,messagesSnapshot="",receivedText=receivedText,lastEventId=null,toolCallsJson=null,usageJson=null,status="GENERATING",createdAt=now,updatedAt=now))}
 fun retryAfterNetwork(){val current=_generation.value;if(current.phase!=AiGenerationPhase.WAITING_FOR_NETWORK)return;job=viewModelScope.launch{_generation.value=_generation.value.copy(phase=AiGenerationPhase.RESUMING);try{val run=app.database.generationRuns().get(current.requestId?:"")?:error("找不到中断的生成记录");_generation.value=_generation.value.copy(phase=AiGenerationPhase.COMPLETED,completeText=run.receivedText);repository.addMessage(MessageEntity(UUID.randomUUID().toString(),run.conversationId,run.requestId,run.requestId,repository.nextMessageSequence(run.conversationId),"assistant",run.receivedText,"INTERRUPTED",System.currentTimeMillis(),modelUsed=run.model));app.database.generationRuns().updateStatus(run.requestId,"COMPLETED",System.currentTimeMillis())}catch(e:Throwable){_generation.value=_generation.value.copy(phase=AiGenerationPhase.FAILED,error=WorkbenchErrorMapper.map(e,0).userFacing.displayText)}finally{job=null}}}
 fun stopAndKeep(){if(_generation.value.phase==AiGenerationPhase.WAITING_FOR_NETWORK||_generation.value.phase==AiGenerationPhase.RESUMING){job?.cancel();_generation.value=_generation.value.copy(phase=AiGenerationPhase.CANCELLED)}}
 fun interrupt(){job?.cancel(CancellationException("用户停止 Agent"))}
 private val _importing=MutableStateFlow(false);val importing:StateFlow<Boolean> =_importing.asStateFlow()
 private val _checkpoints=MutableStateFlow<List<com.uma.workbench.data.ConversationCheckpointEntity>>(emptyList());val checkpoints:StateFlow<List<com.uma.workbench.data.ConversationCheckpointEntity>> =_checkpoints.asStateFlow()
 private val _forkMessage=MutableStateFlow<String?>(null);val forkMessage:StateFlow<String?> =_forkMessage.asStateFlow()
 /** 从某条消息分支出新对话：复制到该消息为止的历史，登记分支关系，切换过去。 */
 fun forkFromMessage(messageId:String){val convId=_conversationId.value?:return;if(job?.isActive==true)return;viewModelScope.launch{runCatching{val src=repository.conversation(convId)?:error("对话不存在");val msgs=app.database.pagedMessages().recentMessages(convId,10_000).reversed();val idx=msgs.indexOfFirst{it.id==messageId};if(idx<0)error("消息不在当前对话");val upto=msgs.subList(0,idx+1);val now=System.currentTimeMillis();val newId=UUID.randomUUID().toString();repository.createConversation(ConversationEntity(newId,"${src.title} · 分支",now,now,workspaceId=src.workspaceId,agentMode=src.agentMode,messageCount=upto.size,tokenTotal=upto.sumOf{(it.tokenCount?:0).toLong()},lastMessagePreview=upto.lastOrNull()?.content?.take(60)));upto.forEach{repository.addMessage(it.copy(id=UUID.randomUUID().toString(),conversationId=newId,sequence=it.sequence))};app.database.conversationBranches().upsert(com.uma.workbench.data.ConversationBranchEntity(id=UUID.randomUUID().toString(),workspaceId=src.workspaceId?:"",parentConversationId=convId,forkedFromMessageId=messageId,title="${src.title} · 分支",purpose=null,createdAt=now,updatedAt=now));_conversationId.value=newId;_forkMessage.value=null}.onFailure{_forkMessage.value=it.message?:it::class.java.simpleName}}}
 /** 在某条消息处创建检查点（存档点）：记录当时对话状态摘要。 */
 fun createCheckpointAt(messageId:String){val convId=_conversationId.value?:return;viewModelScope.launch{runCatching{val conv=repository.conversation(convId)?:error("对话不存在");val msgs=app.database.pagedMessages().recentMessages(convId,10_000);val m=msgs.firstOrNull{it.id==messageId}?:error("消息不在当前对话");app.database.conversationCheckpoints().upsert(com.uma.workbench.data.ConversationCheckpointEntity(id=UUID.randomUUID().toString(),conversationId=convId,messageId=messageId,title=conv.title,summary=m.content.take(500),goals=null,facts=null,openQuestions=null,decisions=null,evidenceRefs=null,createdAt=System.currentTimeMillis()));loadCheckpoints()}.onFailure{_forkMessage.value=it.message?:it::class.java.simpleName}}}
 fun loadCheckpoints(){val convId=_conversationId.value?:return;viewModelScope.launch{runCatching{app.database.conversationCheckpoints().observe(convId).first()}.onSuccess{_checkpoints.value=it}}}
 fun clearForkMessage(){_forkMessage.value=null}
 /** 导入 Agora-Workbench 备份（zip 或裸 conversations.json）到当前工作区。 */
 fun importAgoraBackup(uri:android.net.Uri,onDone:(String)->Unit){val d=activeDocument.value?:return;viewModelScope.launch{_importing.value=true;runCatching{com.uma.workbench.imports.AgoraChatImporter.import(app,uri,d.workspaceId,{c->repository.createConversation(c)},{m->repository.addMessage(m)})}.onSuccess{r->onDone("已导入 ${r.conversations} 个对话、${r.messages} 条消息")}.onFailure{onDone("导入失败：${WorkbenchErrorMapper.map(it,0).userFacing.displayText}")};_importing.value=false}};private suspend fun ensureConversation(t:String):String{_conversationId.value?.let{return it};val now=System.currentTimeMillis();val id=UUID.randomUUID().toString();repository.createConversation(ConversationEntity(id,t,now,now,workspaceId=activeDocument.value?.workspaceId));_conversationId.value=id;return id}

 private val _selection=MutableStateFlow(ConversationSelectionState());val selection:StateFlow<ConversationSelectionState> =_selection.asStateFlow()
 fun enterSelection(conversationId:String?){_selection.value=_selection.value.enter(conversationId)}
 fun toggleSelection(conversationId:String){if(_selection.value.selecting)_selection.value=_selection.value.toggle(conversationId)}
