 fun deleteSelectedConversations()=viewModelScope.launch{val wsId=activeDocument.value?.workspaceId;val ids=_selection.value.selectedIds;if(ids.isEmpty()){_selection.value=_selection.value.copy(error="没有选中的对话");return@launch};_selection.value=_selection.value.copy(deleting=true,error=null);try{if(wsId!=null){repository.deleteConversations(wsId,ids)};_selection.value=ConversationSelectionState();if(_conversationId.value in ids){_conversationId.value=null}}catch(e:Throwable){_selection.value=_selection.value.copy(deleting=false,error=WorkbenchErrorMapper.map(e,0).userFacing.displayText)}}

 private val PAGE_SIZE=50;private var _oldestLoadedSequence=Long.MAX_VALUE;private val _hasMoreMessages=MutableStateFlow(true);val hasMoreMessages:StateFlow<Boolean> =_hasMoreMessages.asStateFlow()
 fun loadOlderMessages(){val convId=_conversationId.value?:return;viewModelScope.launch{val older=app.database.pagedMessages().messagesBefore(convId,_oldestLoadedSequence,PAGE_SIZE);if(older.isEmpty()){_hasMoreMessages.value=false;return@launch};_oldestLoadedSequence=older.minOf{it.sequence};_hasMoreMessages.value=older.size>=PAGE_SIZE}}
 fun resetPaging(){_oldestLoadedSequence=Long.MAX_VALUE;_hasMoreMessages.value=true}
 fun loadRecentMessages(){val convId=_conversationId.value?:return;viewModelScope.launch{val recent=app.database.pagedMessages().recentMessages(convId,PAGE_SIZE);if(recent.isNotEmpty())_oldestLoadedSequence=recent.minOf{it.sequence};_hasMoreMessages.value=recent.size>=PAGE_SIZE}}

 private suspend fun persistAgentRun(requestId:String,conversationId:String,providerId:String,result:com.uma.workbench.agent.ReadonlyAgentRunResult,status:String,error:String?){runCatching{val db=com.uma.workbench.agent.AgentPartnerDatabase.get(app);db.agentRuns().upsert(com.uma.workbench.agent.AgentRunEntity(id=requestId,conversationId=conversationId,providerId=providerId,tier="CHAT",startedAt=System.currentTimeMillis(),completedAt=System.currentTimeMillis(),status=status,model=result.model,inputTokens=result.usage.inputTokens,outputTokens=result.usage.outputTokens,totalTokens=result.usage.totalTokens,roundsCount=result.rounds.size,toolCallsCount=result.rounds.sumOf{it.toolCalls.size},error=error));result.rounds.forEachIndexed{roundIndex,round->round.toolCalls.zip(round.toolOutcomes).forEach{(call,outcome)->db.toolCallRecords().upsert(com.uma.workbench.agent.AgentToolCallRecordEntity(id="${requestId}-${call.id}",runId=requestId,roundIndex=roundIndex,callId=call.id,toolName=call.name,argumentsJson=call.completeArgumentsJson,status=when(outcome){is com.uma.workbench.agent.AgentToolOutcome.Success->"ok";is com.uma.workbench.agent.AgentToolOutcome.Failure->"error"},resultId=when(outcome){is com.uma.workbench.agent.AgentToolOutcome.Success->outcome.result.resultId;is com.uma.workbench.agent.AgentToolOutcome.Failure->null},error=when(outcome){is com.uma.workbench.agent.AgentToolOutcome.Success->null;is com.uma.workbench.agent.AgentToolOutcome.Failure->outcome.failure.completeError},elapsedMillis=when(outcome){is com.uma.workbench.agent.AgentToolOutcome.Success->outcome.result.elapsedMillis;is com.uma.workbench.agent.AgentToolOutcome.Failure->outcome.failure.elapsedMillis},approved=true,timestamp=System.currentTimeMillis()))}}}}
 private suspend fun persistAgentRunFailed(requestId:String,conversationId:String,providerId:String,model:String?,e:Throwable){runCatching{com.uma.workbench.agent.AgentPartnerDatabase.get(app).agentRuns().upsert(com.uma.workbench.agent.AgentRunEntity(id=requestId,conversationId=conversationId,providerId=providerId,tier="CHAT",startedAt=System.currentTimeMillis(),completedAt=System.currentTimeMillis(),status="FAILED",model=model,inputTokens=0,outputTokens=0,totalTokens=0,roundsCount=0,toolCallsCount=0,error=e.message?:e::class.java.simpleName))}}
